using FluentValidation;namespace Namaa.Application.Users.Commands.UpdateUser;public sealed class UpdateUserCommandValidator:AbstractValidator<UpdateUserCommand>{public UpdateUserCommandValidator(){RuleFor(x=>x.Id).GreaterThan(0);RuleFor(x=>x.RoleId).GreaterThan((byte)0);RuleFor(x=>x.FullName).NotEmpty().MaximumLength(200);RuleFor(x=>x.Email).MaximumLength(254).EmailAddress().When(x=>!string.IsNullOrWhiteSpace(x.Email));RuleFor(x=>x.PhoneNumber).MaximumLength(30);RuleFor(x=>x).Must(x=>!string.IsNullOrWhiteSpace(x.Email)||!string.IsNullOrWhiteSpace(x.PhoneNumber)).WithMessage("Email or phone number is required.");}}
